"""Thin HTTP client for pushing findings into secman via POST /api/vulnerabilities/cli-add.

Mirrors secman's own CLI (CliHttpClient.authenticate in the secman repo): the
login response carries no token in its JSON body — the JWT only appears in the
Set-Cookie: secman_auth=<jwt> response header. Subsequent requests send it as
a standard Authorization: Bearer header (Micronaut's bearer-token reader stays
active alongside cookie auth on the secman backend).
"""

from __future__ import annotations

import requests
from tenacity import retry, retry_if_exception_type, stop_after_attempt, wait_exponential

from . import dryrun

_TIMEOUT_S = 30
_RETRY = dict(
    stop=stop_after_attempt(3),
    wait=wait_exponential(multiplier=1, min=2, max=20),
    retry=retry_if_exception_type(requests.exceptions.ConnectionError),
    reraise=True,
)


class SecmanPushError(Exception):
    """Raised on login failure or a rejected cli-add call."""


def _extract_cookie_token(set_cookie_header: str, cookie_name: str = "secman_auth") -> str | None:
    for part in set_cookie_header.split(";"):
        part = part.strip()
        if part.startswith(f"{cookie_name}="):
            return part[len(f"{cookie_name}="):]
    return None


@retry(**_RETRY)
def login(base_url: str, username: str, password: str) -> str:
    """POST /api/auth/login, return the JWT extracted from Set-Cookie."""
    dryrun.guard("authenticate against secman")
    resp = requests.post(
        f"{base_url}/api/auth/login",
        json={"username": username, "password": password},
        timeout=_TIMEOUT_S,
        allow_redirects=False,
    )
    if resp.status_code != 200:
        raise SecmanPushError(f"secman login failed with HTTP {resp.status_code}")

    set_cookie = resp.headers.get("Set-Cookie", "")
    token = _extract_cookie_token(set_cookie)
    if not token:
        raise SecmanPushError("secman login succeeded but no auth token found in Set-Cookie response header")
    return token


@retry(**_RETRY)
def push_vulnerability(
    base_url: str,
    token: str,
    *,
    hostname: str,
    cve: str,
    criticality: str,
    days_open: int,
) -> dict:
    """POST /api/vulnerabilities/cli-add with Authorization: Bearer {token}."""
    dryrun.guard(f"push {cve} for {hostname} to secman")
    resp = requests.post(
        f"{base_url}/api/vulnerabilities/cli-add",
        json={"hostname": hostname, "cve": cve, "criticality": criticality, "daysOpen": days_open},
        headers={"Authorization": f"Bearer {token}"},
        timeout=_TIMEOUT_S,
        allow_redirects=False,
    )
    if resp.status_code != 200:
        raise SecmanPushError(f"cli-add failed with HTTP {resp.status_code}")
    return resp.json()
    if len(external_ids) != len(set(external_ids)):
        raise IntegrationResultError("integration run contains duplicate finding identities")
    body: dict[str, Any] = {
        "scannerId": scanner_id,
        "subjectId": subject.id,
        "status": normalized_status,
        "completeCoverage": False,
        "startedAt": started_at,
        "completedAt": completed_at,
        "metadataJson": json.dumps(metadata or {}, sort_keys=True, separators=(",", ":")),
        "findings": mapped,
    }
    canonical = json.dumps(body, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    body["runKey"] = "secscan-v1:" + hashlib.sha256(canonical.encode()).hexdigest()
    return body


class IntegrationClient:
    """Authenticated client for permitted subjects and atomic run submission."""

    def __init__(self, base_url: str, token: str):
        self._base_url = validate_base_url(base_url)
        self._headers = {"Authorization": f"Bearer {token}"}

    def list_subjects(self, scanner_id: int, *, size: int = 100) -> list[IntegrationSubject]:
        if size < 1 or size > 100:
            raise ValueError("subject page size must be between 1 and 100")
        subjects: list[IntegrationSubject] = []
        page = 0
        while True:
            response = requests.get(
                f"{self._base_url}/api/integrations/v1/scanners/{scanner_id}/subjects",
                headers=self._headers,
                params={"page": page, "size": size},
                timeout=_TIMEOUT_S,
                allow_redirects=False,
            )
            if response.status_code != 200:
                raise IntegrationResultError(
                    f"secman subject discovery failed with HTTP {response.status_code}"
                )
            try:
                payload = response.json()
                subjects.extend(IntegrationSubject.from_api(row) for row in payload["content"])
                total_pages = int(payload["totalPages"])
            except (KeyError, TypeError, ValueError) as exc:
                raise IntegrationResultError("secman subject discovery returned an invalid response") from exc
            page += 1
            if page >= total_pages:
                return subjects

    def submit_run(self, body: Mapping[str, Any]) -> dict[str, Any]:
        dryrun.guard("submit an integration run to secman")
        response = requests.post(
            f"{self._base_url}/api/integrations/v1/runs",
            json=dict(body),
            headers=self._headers,
            timeout=_TIMEOUT_S,
            allow_redirects=False,
        )
        if response.status_code not in (200, 201):
            raise IntegrationResultError(
                f"secman integration run was rejected with HTTP {response.status_code}"
            )
        try:
            return response.json()
        except (TypeError, ValueError) as exc:
            raise IntegrationResultError("secman integration run returned an invalid response") from exc


def push_stored_records(
    store,
    *,
    url: str | None,
    username: str | None,
    password: str | None,
    scanner_id: int,
    github_instance: str,
    dry_run: bool,
) -> tuple[int, int]:
    """Submit terminal snapshots already present in the state database."""
    records = store.all_records()
    if dry_run:
        return len(records), 0

    from . import secman_client
    """Authenticated client for subject discovery and atomic run submission."""

    def __init__(self, base_url: str, token: str) -> None:
        if not token:
            raise SecmanIntegrationError("SecMan token must not be empty")
        self._client = httpx.Client(
            base_url=validate_base_url(base_url),
            headers={"Authorization": f"Bearer {token}"},
            verify=_system_ca_context(),
            timeout=_TIMEOUT_SECONDS,
            follow_redirects=False,
            trust_env=False,
        )

    @classmethod
    def login(cls, base_url: str, username: str, password: str) -> IntegrationClient:
        if not username or not password:
            raise SecmanIntegrationError("SecMan credentials must not be empty")
        instance = cls.__new__(cls)
        instance._client = httpx.Client(
            base_url=validate_base_url(base_url),
            verify=_system_ca_context(),
            timeout=_TIMEOUT_SECONDS,
            follow_redirects=False,
            trust_env=False,
        )
        try:
            response = instance._client.post(
                "/api/auth/login",
                json={"username": username, "password": password},
            )
        except httpx.HTTPError as error:
            instance.close()
            raise SecmanIntegrationError("SecMan login request failed") from error
        if response.status_code not in {200, 204}:
            instance.close()
            raise SecmanIntegrationError(f"SecMan login failed with HTTP {response.status_code}")
        return instance

    def close(self) -> None:
        self._client.close()

    def __enter__(self) -> Self:
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

    def list_subjects(self, scanner_id: int, *, size: int = 100) -> list[IntegrationSubject]:
        if size < 1 or size > 100:
            raise ValueError("subject page size must be between 1 and 100")
        subjects: list[IntegrationSubject] = []
        page = 0
        while True:
            try:
                response = self._client.get(
                    f"/api/integrations/v1/scanners/{scanner_id}/subjects",
                    params={"page": page, "size": size},
                )
            except httpx.HTTPError as error:
                raise SecmanIntegrationError("SecMan subject discovery request failed") from error
            if response.status_code != 200:
                raise SecmanIntegrationError(
                    f"SecMan subject discovery failed with HTTP {response.status_code}"
                )
            try:
                payload = response.json()
                subjects.extend(IntegrationSubject.from_api(row) for row in payload["content"])
                total_pages = int(payload["totalPages"])
            except (KeyError, TypeError, ValueError) as error:
                raise SecmanIntegrationError(
                    "SecMan subject discovery returned an invalid response"
                ) from error
            page += 1
            if page >= total_pages:
                return subjects

    def submit_run(self, body: Mapping[str, Any]) -> dict[str, Any]:
        try:
            response = self._client.post("/api/integrations/v1/runs", json=dict(body))
        except httpx.HTTPError as error:
            raise SecmanIntegrationError("SecMan run submission request failed") from error
        if response.status_code not in {200, 201}:
            raise SecmanIntegrationError(
                f"SecMan run submission failed with HTTP {response.status_code}"
            )
        try:
            payload = response.json()
        except ValueError as error:
            raise SecmanIntegrationError("SecMan run submission returned invalid JSON") from error
        if not isinstance(payload, dict):
            raise SecmanIntegrationError("SecMan run submission returned an invalid response")
        return payload
"""Optional secman backend integration (Phase 1 — no backend change needed).

Flow: POST /api/auth/login (JWT arrives as `secman_auth` cookie, also usable
as Bearer) -> PUT /api/assets/import per discovered asset (idempotent upsert,
tags merged additively) -> POST /api/scan/upload-nmap for the raw nmap XML
(creates Scan/ScanResult/ScanPort rows and links ports to assets in secman).

Contract verified against src/backendng (AssetController.importAsset,
ScanController.uploadNmapScan, AuthController.login). If endpoints change,
re-verify path / method / request fields / response fields / roles.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

import httpx

from .config import SecmanConfig
from .models import DiscoveredHost, Enrichment

USER_AGENT = "secman-intra-mon/0.1"
LOGIN_PATH = "/api/auth/login"
IMPORT_ASSET_PATH = "/api/assets/import"
UPLOAD_NMAP_PATH = "/api/scan/upload-nmap"


class SecmanError(Exception):
    pass


@dataclass
class PushSummary:
    assets_created: int = 0
    assets_updated: int = 0
    xml_uploads: int = 0
    errors: list[str] = field(default_factory=list)


class SecmanClient:
    def __init__(self, config: SecmanConfig, timeout: float = 30.0):
        self._config = config
        self._client = httpx.Client(
            base_url=config.base_url,
            timeout=timeout,
            headers={"User-Agent": USER_AGENT},
        )
        if config.token:
            self._client.headers["Authorization"] = f"Bearer {config.token}"

    @property
    def username(self) -> str | None:
        return self._config.username

    def close(self) -> None:
        self._client.close()

    def __enter__(self) -> SecmanClient:
        return self

    def __exit__(self, *_exc: object) -> None:
        self.close()

    # -- auth ----------------------------------------------------------------

    def login(self) -> list[str]:
        """Authenticate with username/password; returns the user's roles."""
        if self._config.token:
            return []  # token auth: roles unknown, validated on first request
        try:
            response = self._client.post(
                LOGIN_PATH,
                json={
                    "username": self._config.username,
                    "password": self._config.password,
                },
            )
        except httpx.HTTPError as exc:
            raise SecmanError(f"cannot reach secman at {self._config.base_url}: {exc}") from exc
        if response.status_code == 401:
            raise SecmanError("secman login failed: invalid credentials")
        if response.status_code != 200:
            raise SecmanError(f"secman login failed: HTTP {response.status_code} {response.text[:200]}")
        jwt = response.cookies.get("secman_auth")
        if not jwt:
            raise SecmanError("secman login succeeded but no secman_auth cookie was returned")
        self._client.headers["Authorization"] = f"Bearer {jwt}"
        roles = response.json().get("roles", [])
        if not isinstance(roles, list):
            roles = []
        return [str(role) for role in roles]

    # -- ingestion -----------------------------------------------------------

    def push_asset(self, host: DiscoveredHost, owner: str, enrichment: Enrichment | None = None) -> bool:
        """Idempotent upsert of one asset. Returns True when newly created."""
        description = f"Discovered by secman_intra_mon ({host.discovered_via or 'scan'})"
        if enrichment and enrichment.role:
            description += f" — {enrichment.role}"
        body: dict[str, Any] = {
            "name": host.display_name(),
            "type": "Network Host",
            "owner": owner,
            "ip": host.ip,
            "networkZone": "INTERNAL",
            "description": description,
            "tags": self._asset_tags(host, enrichment),
        }
        response = self._request("PUT", IMPORT_ASSET_PATH, json=body)
        payload = response.json()
        return bool(payload.get("created", False))

    def upload_nmap_xml(self, xml_text: str, filename: str) -> dict[str, Any]:
        """Upload raw `nmap -oX` output; returns secman's ScanSummaryDTO."""
        response = self._request(
            "POST",
            UPLOAD_NMAP_PATH,
            files={"file": (filename, xml_text, "application/xml")},
        )
        return dict(response.json())

    # -- helpers -------------------------------------------------------------

    def _request(self, method: str, path: str, **kwargs: Any) -> httpx.Response:
        try:
            response = self._client.request(method, path, **kwargs)
        except httpx.HTTPError as exc:
            raise SecmanError(f"secman request {method} {path} failed: {exc}") from exc
        if response.status_code in (401, 403):
            raise SecmanError(
                f"secman rejected {method} {path} (HTTP {response.status_code}) — "
                "the account needs the ADMIN role for asset import and nmap upload"
            )
        if response.status_code >= 400:
            raise SecmanError(
                f"secman {method} {path} failed: HTTP {response.status_code} {response.text[:300]}"
            )
        return response

    @staticmethod
    def _asset_tags(host: DiscoveredHost, enrichment: Enrichment | None = None) -> dict[str, str]:
        tags: dict[str, str] = {"discovered_via": host.discovered_via or "scan"}
        if host.mac:
            tags["mac"] = host.mac
        if host.mac_vendor:
            tags["mac_vendor"] = host.mac_vendor
        if host.os_guess:
            tags["os_guess"] = host.os_guess
        if host.open_ports:
            tags["open_ports"] = ",".join(
                f"{p.port}/{p.protocol}" for p in sorted(host.open_ports, key=lambda p: p.port)
            )
        if enrichment:
            if enrichment.device_type:
                tags["device_type"] = enrichment.device_type
            if enrichment.criticality:
                tags["criticality"] = enrichment.criticality
        return tags


def push_hosts(
    client: SecmanClient,
    hosts: list[DiscoveredHost],
    owner: str,
    xml_documents: list[str] | None = None,
    enrichments: dict[str, Enrichment] | None = None,
) -> PushSummary:
    """Push all discovered assets, then upload nmap XML. Never raises on
    individual asset failures — errors are collected into the summary."""
    summary = PushSummary()
    for host in hosts:
        try:
            if client.push_asset(host, owner, (enrichments or {}).get(host.ip)):
                summary.assets_created += 1
            else:
                summary.assets_updated += 1
        except (SecmanError, ValueError) as exc:
            summary.errors.append(f"{host.ip}: {exc}")
